begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select public.pakupai_profile_bootstrap();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);select public.pakupai_profile_bootstrap();
reset role;
do $$declare a uuid:='00000000-0000-4000-8000-000000000011';i uuid:='00000000-0000-4000-8000-000000000021';r jsonb;n integer;wa uuid;wb uuid;fa uuid;fb uuid;bundle uuid;begin
 select id into wa from public.pakupai_workspaces where owner_id='00000000-0000-4000-8000-000000000001';
 select id into wb from public.pakupai_workspaces where owner_id='00000000-0000-4000-8000-000000000002';
 perform public.pakupai_workspace_rpc('invite',jsonb_build_object('user_id','00000000-0000-4000-8000-000000000001','id',i,'hash','test-invite','hours',24,'label','test'));
 r:=public.pakupai_workspace_rpc('join',jsonb_build_object('invite_hash','test-invite','id',a,'key_hash','test-key','name','Test agent'));
 if r->>'status'<>'pending' then raise exception 'pending_failure';end if;
 if public.pakupai_workspace_rpc('join',jsonb_build_object('invite_hash','test-invite','id',gen_random_uuid(),'key_hash','test-key2','name','Second'))->>'error'<>'invite_invalid_expired_or_used' then raise exception 'invite_reuse';end if;
 if public.pakupai_workspace_rpc('agent_post','{"hash":"test-key","text":"bad"}') ->>'error'<>'not_approved' then raise exception 'pending_post';end if;
 if public.pakupai_workspace_rpc('transition',jsonb_build_object('user_id','00000000-0000-4000-8000-000000000002','id',a,'action','approve'))->>'error'<>'not_found' then raise exception 'wrong_owner';end if;
 perform public.pakupai_workspace_rpc('transition',jsonb_build_object('user_id','00000000-0000-4000-8000-000000000001','id',a,'action','approve'));
 for n in 1..30 loop r:=public.pakupai_workspace_rpc('agent_post','{"hash":"test-key","text":"ok"}');if r->>'ok'<>'true' then raise exception 'post_failed';end if;end loop;
 if public.pakupai_workspace_rpc('agent_post','{"hash":"test-key","text":"too many"}')->>'error'<>'rate_limited' then raise exception 'rate_limit_failed';end if;
 insert into public.pakupai_room_messages(workspace_id,text) values(wb,'PRIVATE B');
 if jsonb_array_length(public.pakupai_workspace_rpc('agent_messages','{"hash":"test-key"}')->'messages')<>30 then raise exception 'messages_leak';end if;
 insert into public.pakupai_library_files(workspace_id,name,body) values(wa,'A','assigned A') returning id into fa;
 insert into public.pakupai_library_files(workspace_id,name,body) values(wb,'B','PRIVATE B') returning id into fb;
 insert into public.pakupai_library_bundles(workspace_id,name) values(wa,'A') returning id into bundle;
 insert into public.pakupai_library_bundle_files values(bundle,fa,wa,0);
 if jsonb_array_length(public.pakupai_workspace_rpc('agent_files','{"hash":"test-key"}')->'files')<>0 then raise exception 'unassigned_file_leak';end if;
 insert into public.pakupai_room_bundles values(a,bundle,wa);
 r:=public.pakupai_workspace_rpc('agent_files','{"hash":"test-key"}');if r->'files'->0->>'body'<>'assigned A' or jsonb_array_length(r->'files')<>1 then raise exception 'files_leak';end if;
 perform public.pakupai_workspace_rpc('transition',jsonb_build_object('user_id','00000000-0000-4000-8000-000000000001','id',a,'action','revoke'));
 if public.pakupai_workspace_rpc('agent_messages','{"hash":"test-key"}')->>'error'<>'revoked' then raise exception 'revoked_access';end if;
end$$;
select 'passed: single-use, pending/revoked, wrong-owner, messages/files isolation, rate limit' tests;
rollback;
